'use strict';
// Festival layers of the village («Посиделки», «Новый год», «Масленица», «Весенние цветы»), generated by
// scripts/art/village/fest_<id>.js; reproducibility is checked in scripts/art/village/test_reproducible.py.
const test=require('node:test'),assert=require('node:assert/strict'),fs=require('fs'),path=require('path');
const stat=path.join(__dirname,'../../qw_farm/static');
const app=fs.readFileSync(path.join(stat,'app.js'),'utf8'),css=fs.readFileSync(path.join(stat,'style.css'),'utf8');
const api=fs.readFileSync(path.join(__dirname,'../../qw_farm/api.py'),'utf8');
// festival id -> [layer file, size budget]: the layers load only while their festival runs; the new year one dresses every
// roof and lays snow over the whole village (ground outlines, caps on ~1500 trees)
const LAYERS={posidelki:['village-fest-posidelki.svg',120000],new_year:['village-fest-new_year.svg',450000],
 maslenitsa:['village-fest-maslenitsa.svg',120000],spring_flowers:['village-fest-spring_flowers.svg',160000]};

for(const [id,[file,budget]] of Object.entries(LAYERS))test(`${id} layer: vector only, CSP-safe, day / night / decor groups over the 2400x1800 world`,()=>{
 const svg=fs.readFileSync(path.join(stat,file),'utf8');
 assert.match(svg,/^<svg [^>]*viewBox="0 0 2400 1800"/);
 assert.doesNotMatch(svg,/<image|data:|<style|style=|<script|href=/i,'no raster, inline style or script');
 for(const g of ['vf-decor','vf-day','vf-night','vf-smoke vf-s1','vf-smoke vf-s3'])assert.match(svg,new RegExp(`<g class="${g}">`));
 assert.ok(svg.length<budget,'stays light');
 assert.ok(api.includes(`'${file}'`),'served as an asset');
 assert.ok(app.includes(`${id}:'${file}'`),'listed in VILLAGE_FEST');
 assert.ok(css.includes(`:root[data-festival=${id}][data-festival-decor=on] .village-fest[data-fest=${id}]`),'shown by the html flags');
});
test('festival layers: fetched only for their festival, base under the night tint, glow above it',()=>{
 assert.match(app,/const VILLAGE_FEST=\{posidelki:'village-fest-posidelki\.svg',/);
 assert.match(app,/d\?\.festivalDecor==='on'\?d\.festival:''/,'nothing is fetched while the decor switch is off');
 assert.match(app,/world\.append\(villageMerchantLayer\('base'\),villageFestLayer\('base'\),sun,villageFx\(\),night,villageFestLayer\('glow'\),/,'base under the night tint, glow above it');
 assert.match(app,/FEST\.applyWorld\(view\);syncVillageFest\(\);/);
 assert.match(css,/\.village-fest\{position:absolute;inset:0;pointer-events:none;display:none\}/);
 assert.match(css,/:root:not\(\[data-farm-theme=night\]\) \.village-fest-glow \.vf-night\{display:none\}/);
 assert.match(css,/prefers-reduced-motion:no-preference\)\{\s*\.vf-smoke\{animation/);
});
